INSERT INTO __LEGACY_SCHEMA__.taxa (id, public_id, scientific_name, rank, taxonomic_status, accepted_name, parent_taxon_id, description, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000101', 'taxon-echinopsis-pachanoi', 'Echinopsis pachanoi', 'species', 'accepted', NULL, NULL, 'Ficha pública inicial anclada a POWO/Kew y GBIF. Conserva la diferencia entre una especie aceptada en POWO, una coincidencia GBIF con estado sinónimo y los nombres culturales documentados en contextos específicos.', '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.taxa (id, public_id, scientific_name, rank, taxonomic_status, accepted_name, parent_taxon_id, description, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000155', 'taxon-opuntia-ficus-indica', 'Opuntia ficus-indica', 'species', 'accepted', NULL, NULL, 'Ficha pública inicial anclada a POWO/Kew y GBIF. El registro distingue el rango nativo indicado por una fuente taxonómica de una ocurrencia contemporánea externa revisada; una observación no se presenta como distribución nativa.', '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.taxa (id, public_id, scientific_name, rank, taxonomic_status, accepted_name, parent_taxon_id, description, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000174', 'taxon-pleurotus-ostreatus', 'Pleurotus ostreatus', 'species', 'accepted', NULL, NULL, 'Ficha pública inicial de un hongo basidiomiceto anclada a GBIF Backbone. El corpus incorpora una guía experimental de cultivo con fuente abierta, condiciones situadas y límites explícitos; la ecología funcional y las relaciones culturales permanecen pendientes de fuentes específicas.', '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');


