INSERT INTO __LEGACY_SCHEMA__.claims (id, public_id, subject_type, subject_id, predicate, object_type, object_id, object_uri, object_text, value_json, assertion_type, evidence_level, author_agent_id, source_id, source_record_id, author_perspective, recorded_on, visibility, license_uri, review_status, superseded_by, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000216', 'claim-utn-echinopsis-pachanoi-habitat-model-2017', 'taxon', '00000000-0000-4000-8000-000000000101', 'distributionModel', NULL, NULL, NULL, 'La tesis de Tituaña Armas modeló la distribución potencial del hábitat de Echinopsis pachanoi en el norte de los Andes ecuatorianos a partir de 63 hallazgos y variables bioclimáticas; reportó la precipitación media anual y la vegetación como variables relevantes para el modelo y delimitó un área potencial de 459,64 km² para manejo.', NULL, 'academic_publication', 'documented', NULL, '00000000-0000-4000-8000-000000000212', '00000000-0000-4000-8000-000000000208', 'Tituaña Armas y Universidad Técnica del Norte; paráfrasis editorial de WACHUMA, sin convertir el modelo potencial en una distribución confirmada.', '2017-11-13', 'public', 'https://creativecommons.org/licenses/by-nc-nd/4.0/', 'under-review', NULL, '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.claims (id, public_id, subject_type, subject_id, predicate, object_type, object_id, object_uri, object_text, value_json, assertion_type, evidence_level, author_agent_id, source_id, source_record_id, author_perspective, recorded_on, visibility, license_uri, review_status, superseded_by, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000217', 'claim-unprg-echinopsis-pachanoi-rhizosphere-2023', 'taxon', '00000000-0000-4000-8000-000000000101', 'rhizosphereStudy', NULL, NULL, NULL, 'La tesis de Núñez Montenegro estudió aislamientos de Bacillus spp. y Pseudomonas spp. de la rizosfera de Echinopsis pachanoi “San Pedro hembra” en Lambayeque y evaluó su potencial promotor del crecimiento en Solanum lycopersicum bajo estrés hídrico. No constituye una guía de cultivo del cactus ni demuestra que esos consorcios sean un requisito de la especie.', NULL, 'academic_publication', 'documented', NULL, '00000000-0000-4000-8000-000000000213', '00000000-0000-4000-8000-000000000209', 'Núñez Montenegro y Universidad Nacional Pedro Ruiz Gallo; paráfrasis editorial acotada al resumen del registro y separada de recomendaciones de cultivo.', '2026-08-27', 'public', 'https://creativecommons.org/licenses/by-sa/4.0/', 'under-review', NULL, '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.claims (id, public_id, subject_type, subject_id, predicate, object_type, object_id, object_uri, object_text, value_json, assertion_type, evidence_level, author_agent_id, source_id, source_record_id, author_perspective, recorded_on, visibility, license_uri, review_status, superseded_by, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000218', 'claim-scielo-echinopsis-pachanoi-rhizosphere-2025', 'taxon', '00000000-0000-4000-8000-000000000101', 'rhizosphereStudy', NULL, NULL, NULL, 'El artículo de Cedeño-Moreira y colaboradores estudia consorcios bacterianos con actividad promotora del crecimiento asociados a la rizosfera de Echinopsis pachanoi. WACHUMA lo registra como investigación de microbiología vegetal, no como evidencia suficiente para prescribir una práctica de cultivo.', NULL, 'academic_publication', 'documented', NULL, '00000000-0000-4000-8000-000000000215', '00000000-0000-4000-8000-000000000211', 'Cedeño-Moreira, Arellano-Ibarra, Álvarez-Sánchez, Espinoza-Guerra, Acosta-Farias y Pico-Saltos; paráfrasis editorial del título y metadatos del artículo.', '2026-08-27', 'public', 'https://creativecommons.org/licenses/by-nc-nd/4.0/deed.es', 'under-review', NULL, '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.claims (id, public_id, subject_type, subject_id, predicate, object_type, object_id, object_uri, object_text, value_json, assertion_type, evidence_level, author_agent_id, source_id, source_record_id, author_perspective, recorded_on, visibility, license_uri, review_status, superseded_by, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000219', 'claim-untumbes-echinopsis-metabolomics-2020', 'taxon', '00000000-0000-4000-8000-000000000101', 'chemicalProfileStudy', NULL, NULL, NULL, 'La tesis de Chang Coronado caracteriza Hylocereus y Echinopsis mediante marcadores ITS2, proteómica y metabolómica; el registro incluye Echinopsis pachanoi y especies cercanas y reporta perfiles MS/MS de mescalina para cuatro especies de Echinopsis. Es evidencia de un estudio analítico concreto, no una composición universal ni una recomendación de consumo.', NULL, 'academic_publication', 'documented', NULL, '00000000-0000-4000-8000-000000000214', '00000000-0000-4000-8000-000000000210', 'Chang Coronado y Universidad Nacional de Tumbes; paráfrasis editorial del registro de tesis, con alcance limitado a las muestras y métodos descritos por la autora.', '2026-08-27', 'public', 'https://creativecommons.org/licenses/by/4.0/', 'under-review', NULL, '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.claims (id, public_id, subject_type, subject_id, predicate, object_type, object_id, object_uri, object_text, value_json, assertion_type, evidence_level, author_agent_id, source_id, source_record_id, author_perspective, recorded_on, visibility, license_uri, review_status, superseded_by, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000145', 'claim-powo-echinopsis-pachanoi-accepted', 'taxon', '00000000-0000-4000-8000-000000000101', 'taxonomicStatus', NULL, NULL, NULL, 'POWO registra Echinopsis pachanoi como especie aceptada; su rango nativo se indica desde el sur de Ecuador hasta Perú.', NULL, 'taxonomic_fact', 'documented', NULL, '00000000-0000-4000-8000-000000000143', '00000000-0000-4000-8000-000000000141', 'Plants of the World Online; lectura editorial de WACHUMA.', '2026-08-23', 'public', 'CC BY 3.0', 'accepted', NULL, '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.claims (id, public_id, subject_type, subject_id, predicate, object_type, object_id, object_uri, object_text, value_json, assertion_type, evidence_level, author_agent_id, source_id, source_record_id, author_perspective, recorded_on, visibility, license_uri, review_status, superseded_by, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000146', 'claim-gbif-echinopsis-pachanoi-name-match', 'taxon', '00000000-0000-4000-8000-000000000101', 'gbifNameMatch', NULL, NULL, NULL, 'GBIF Backbone devuelve una coincidencia exacta para Echinopsis pachanoi, con estado SYNONYM y acceptedUsageKey 11093098.', NULL, 'taxonomic_fact', 'documented', NULL, '00000000-0000-4000-8000-000000000144', '00000000-0000-4000-8000-000000000142', 'GBIF Backbone Taxonomy; se conserva la diferencia con la evaluación editorial de POWO.', '2026-08-23', 'public', 'CC BY 4.0', 'accepted', NULL, '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.claims (id, public_id, subject_type, subject_id, predicate, object_type, object_id, object_uri, object_text, value_json, assertion_type, evidence_level, author_agent_id, source_id, source_record_id, author_perspective, recorded_on, visibility, license_uri, review_status, superseded_by, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000153', 'claim-powo-echinopsis-pachanoi-native-range', 'taxon', '00000000-0000-4000-8000-000000000101', 'nativeRange', NULL, NULL, NULL, 'Plants of the World Online indica un rango nativo desde el sur de Ecuador hasta Perú.', NULL, 'taxonomic_fact', 'documented', NULL, '00000000-0000-4000-8000-000000000143', '00000000-0000-4000-8000-000000000141', 'Plants of the World Online; lectura editorial de WACHUMA.', '2026-08-23', 'public', 'CC BY 3.0', 'accepted', NULL, '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
