INSERT INTO __LEGACY_SCHEMA__.claims (id, public_id, subject_type, subject_id, predicate, object_type, object_id, object_uri, object_text, value_json, assertion_type, evidence_level, author_agent_id, source_id, source_record_id, author_perspective, recorded_on, visibility, license_uri, review_status, superseded_by, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000179', 'claim-gbif-pleurotus-ostreatus-name-match', 'taxon', '00000000-0000-4000-8000-000000000174', 'gbifNameMatch', NULL, NULL, NULL, 'GBIF Backbone devuelve usageKey 2526530 para Pleurotus ostreatus y conserva la clasificación Fungi · Basidiomycota · Agaricomycetes · Agaricales · Pleurotaceae.', NULL, 'taxonomic_fact', 'documented', NULL, '00000000-0000-4000-8000-000000000177', '00000000-0000-4000-8000-000000000176', 'GBIF Backbone Taxonomy; lectura editorial de WACHUMA.', '2026-08-23', 'public', 'CC BY 4.0', 'accepted', NULL, '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');
