INSERT INTO __LEGACY_SCHEMA__.claims (id, public_id, subject_type, subject_id, predicate, object_type, object_id, object_uri, object_text, value_json, assertion_type, evidence_level, author_agent_id, source_id, source_record_id, author_perspective, recorded_on, visibility, license_uri, review_status, superseded_by, created_at, updated_at) VALUES ('00000000-0000-4000-8000-000000000139', 'claim-echinopsis-pachanoi-historical-combination', 'taxon', '00000000-0000-4000-8000-000000000101', 'historicalContext', NULL, NULL, NULL, 'WACHUMA conserva Trichocereus pachanoi como combinación taxonómica histórica relacionada con la ficha de Echinopsis pachanoi; no la utiliza para resolver nombres culturales ni como equivalencia taxonómica absoluta.', NULL, 'editorial_interpretation', 'documented', '00000000-0000-4000-8000-000000000131', '00000000-0000-4000-8000-000000000144', '00000000-0000-4000-8000-000000000142', 'Interpretación editorial de WACHUMA basada en la coincidencia taxonómica de GBIF Backbone; la perspectiva se conserva separada del proveedor.', '2026-08-23', 'public', 'CC BY 4.0', 'accepted', NULL, '2026-09-05 13:31:37.963744-04', '2026-09-05 13:31:37.963744-04');


