INSERT INTO __LEGACY_SCHEMA__.growing_guides (id, guide_key, version, title, taxon_id, biological_entity_id, author_agent_id, climate_context, technique_context, region_context, status, summary, created_at, public_id, coverage) VALUES ('00000000-0000-4000-8000-000000000191', 'pleurotus-ostreatus-debonis-2026', 1, 'Guía experimental de cultivo · Pleurotus ostreatus · De Bonis et al. 2026', NULL, '00000000-0000-4000-8000-000000000175', NULL, 'Sala de cultivo controlada; 23 °C durante incubación y 18 °C durante los dos primeros flushes del ensayo', 'Bolsas de sustrato esterilizado, spawn de grano y tratamientos de luz LED; protocolo experimental, no receta universal', 'Penn State, State College, Estados Unidos; adaptar cualquier aplicación a la cepa, infraestructura y clima local', 'archived', 'Guía versionada y acotada a un ensayo abierto que comparó sustratos y longitudes de onda en Pleurotus ostreatus. Cada afirmación conserva el contexto experimental y no se presenta como una regla taxonómica general.', '2026-09-05 13:31:37.963744-04', 'guide-pleurotus-ostreatus-debonis-2026-v1', '[{"status": "documented", "sectionKey": "propagation"}, {"status": "documented", "sectionKey": "substrate"}, {"status": "not_documented", "sectionKey": "watering"}, {"status": "documented", "sectionKey": "light"}, {"status": "documented", "sectionKey": "temperature"}, {"status": "not_documented", "sectionKey": "humidity"}, {"status": "not_documented", "sectionKey": "nutrition"}, {"status": "not_documented", "sectionKey": "calendar"}, {"status": "not_documented", "sectionKey": "pests"}, {"status": "not_documented", "sectionKey": "diseases"}, {"note": "El ensayo publicado no estudia trasplante.", "status": "not_applicable", "sectionKey": "transplant"}, {"status": "not_documented", "sectionKey": "fruiting"}, {"status": "documented", "sectionKey": "harvest"}, {"status": "documented", "sectionKey": "observations"}, {"status": "documented", "sectionKey": "bibliography"}]');


