INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000125', '00000000-0000-4000-8000-000000000124', 'propagation', 'Pendiente de documentar métodos de propagación con una fuente verificable y contexto regional.', 'unverified', '00000000-0000-4000-8000-000000000112', 'editorial_interpretation', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000126', '00000000-0000-4000-8000-000000000124', 'substrate', 'Pendiente de documentar sustrato, drenaje y condiciones de cultivo; no es una recomendación publicada.', 'unverified', '00000000-0000-4000-8000-000000000112', 'editorial_interpretation', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000127', '00000000-0000-4000-8000-000000000124', 'observations', 'Registrar aquí observaciones contemporáneas fechadas del jardín, separadas de la bibliografía.', 'reported', '00000000-0000-4000-8000-000000000112', 'contemporary_observation', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000149', '00000000-0000-4000-8000-000000000148', 'substrate', 'Para cactáceas y suculentas en contenedor, RHS recomienda un medio muy drenante y con material granular que evite el encharcamiento. Es una orientación general, no una mezcla validada específicamente para Echinopsis pachanoi.', 'documented', '00000000-0000-4000-8000-000000000147', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000150', '00000000-0000-4000-8000-000000000148', 'watering', 'RHS recomienda regar de forma abundante cuando la superficie del sustrato está seca durante el periodo de crecimiento y dejar escurrir el exceso; el calendario depende del clima y del contenedor.', 'documented', '00000000-0000-4000-8000-000000000147', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000151', '00000000-0000-4000-8000-000000000148', 'propagation', 'RHS indica que un esqueje debe secar y formar callo antes de colocarse en un medio de enraizamiento ligeramente húmedo; la fuente describe cactáceas y suculentas de forma general.', 'documented', '00000000-0000-4000-8000-000000000147', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000152', '00000000-0000-4000-8000-000000000148', 'temperature', 'Para cactáceas de interior en el contexto británico, RHS describe un reposo otoñal/invernal con condiciones más frescas y riego mínimo o nulo; no debe extrapolarse sin revisar el clima local.', 'documented', '00000000-0000-4000-8000-000000000147', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000167', '00000000-0000-4000-8000-000000000166', 'light', 'RHS sitúa Opuntia ficus-indica a pleno sol y describe condiciones de luz plena en cultivo bajo vidrio; la respuesta concreta depende del clima y de la aclimatación del ejemplar.', 'documented', '00000000-0000-4000-8000-000000000165', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000168', '00000000-0000-4000-8000-000000000166', 'substrate', 'RHS recomienda, para cultivo bajo vidrio, un compost sin turba y de drenaje rápido, de base franca con arena gruesa añadida, o un compost comercial para cactus sin turba.', 'documented', '00000000-0000-4000-8000-000000000165', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000169', '00000000-0000-4000-8000-000000000166', 'watering', 'RHS indica dejar secar el compost antes de regar durante el crecimiento en primavera, verano y comienzos de otoño, y suspender el riego durante el reposo invernal.', 'documented', '00000000-0000-4000-8000-000000000165', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000170', '00000000-0000-4000-8000-000000000166', 'nutrition', 'En el contexto de cultivo descrito por RHS, puede aplicarse un fertilizante líquido equilibrado tres o cuatro veces durante el periodo de crecimiento y suspenderse en invierno.', 'documented', '00000000-0000-4000-8000-000000000165', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000171', '00000000-0000-4000-8000-000000000166', 'propagation', 'RHS describe propagación por semilla en primavera después de un remojo previo y enraizamiento de segmentos de tallo en verano; recomienda evitar el contacto directo con las espinas.', 'documented', '00000000-0000-4000-8000-000000000165', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000172', '00000000-0000-4000-8000-000000000166', 'pests', 'El perfil RHS señala susceptibilidad a cochinillas escama y cochinillas algodonosas.', 'documented', '00000000-0000-4000-8000-000000000165', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000173', '00000000-0000-4000-8000-000000000166', 'diseases', 'RHS indica que, aunque suele presentar pocas enfermedades, Opuntia ficus-indica puede sufrir pudrición de raíces en suelo húmedo o con drenaje deficiente.', 'documented', '00000000-0000-4000-8000-000000000165', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000192', '00000000-0000-4000-8000-000000000191', 'substrate', 'El ensayo comparó paja de trigo y una mezcla de 75% de cascarilla de algodón con 25% de paja de trigo; preparó los sustratos con un rango de humedad de 65–70%. Estas formulaciones describen el ensayo y no una receta universal.', 'documented', '00000000-0000-4000-8000-000000000190', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000193', '00000000-0000-4000-8000-000000000191', 'propagation', 'En el protocolo experimental, las bolsas se esterilizaron durante 20 minutos a 121 °C, se dejaron enfriar y se inocularon con spawn de Pleurotus ostreatus al 3% del peso del sustrato.', 'documented', '00000000-0000-4000-8000-000000000190', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000194', '00000000-0000-4000-8000-000000000191', 'temperature', 'La sala del ensayo se mantuvo a 23 °C durante la incubación y se redujo a 18 °C durante el primer y segundo flush; son condiciones del experimento de De Bonis et al., no un rango universal para todas las cepas.', 'documented', '00000000-0000-4000-8000-000000000190', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000195', '00000000-0000-4000-8000-000000000191', 'light', 'El estudio aplicó tratamientos LED durante 8 horas diarias, con una intensidad de 26–28 μmol m⁻² s⁻¹, comparando luz roja, azul, blanca, combinada y oscuridad; sus resultados no establecen todavía un protocolo lumínico universal.', 'documented', '00000000-0000-4000-8000-000000000190', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000196', '00000000-0000-4000-8000-000000000191', 'harvest', 'Los cuerpos fructíferos se cosecharon en madurez comercial, cuando los bordes del sombrero comenzaban a quedar paralelos al suelo y antes de curvarse hacia arriba; el ensayo siguió dos flushes.', 'documented', '00000000-0000-4000-8000-000000000190', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.growing_guide_claims (id, growing_guide_id, section_key, statement, evidence_level, source_id, assertion_type, created_at) VALUES ('00000000-0000-4000-8000-000000000197', '00000000-0000-4000-8000-000000000191', 'observations', 'El rendimiento y la morfología respondieron conjuntamente al sustrato y a la luz, por lo que la guía debe leerse como un protocolo reproducible y situado, no como una instrucción única para cualquier cepa o región.', 'documented', '00000000-0000-4000-8000-000000000190', 'horticultural_guidance', '2026-09-05 13:31:37.963744-04');


ALTER TABLE __LEGACY_SCHEMA__.growing_guide_claims ENABLE TRIGGER ALL;

