INSERT INTO __LEGACY_SCHEMA__.material_fixture_bindings (id, public_id, material_fixture_id, layer, target, interpretation, notes, created_at) VALUES ('285d44c1-cb81-417e-389e-91d9522e5d0a', 'material-binding-echinopsis-morphology', '0963bd70-da76-4362-0f26-c64ccdb4688d', 'morphology', 'geometry', 'symbolic', 'La geometría puede evocar un cactus columnar; no sustituye una descripción morfológica ni una captura de ejemplar.', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.material_fixture_bindings (id, public_id, material_fixture_id, layer, target, interpretation, notes, created_at) VALUES ('8179f823-30c4-4c60-0881-cbf42459da79', 'material-binding-echinopsis-cultivation', '0963bd70-da76-4362-0f26-c64ccdb4688d', 'cultivation', 'animation', 'symbolic', 'La animación queda reservada para representar etapas del manual de cultivo cuando existan datos de ejemplares.', '2026-09-05 13:31:37.963744-04');
INSERT INTO __LEGACY_SCHEMA__.material_fixture_bindings (id, public_id, material_fixture_id, layer, target, interpretation, notes, created_at) VALUES ('eb4cbeed-000c-4f5e-1e80-ed82451e71a6', 'material-binding-opuntia-morphology', '55813463-07e7-46ea-0925-306080347d72', 'morphology', 'geometry', 'symbolic', 'La forma visual alude a cladodios; no es una medición morfológica ni una imagen de la ocurrencia GBIF.', '2026-09-05 13:31:37.963744-04');
